# crud_ui/query.py — ordenação no banco quando o spec é nome de coluna
def sorted_query(
    query: Query[EntityT], sort: str, order: str,
    sort_fields: Mapping[str, SortSpec[EntityT]], model: type[EntityT],
) -> Query[EntityT] | None:
    spec = sort_fields.get(sort)
    if not isinstance(spec, str):
        return None  # lambda: cai no caminho antigo, em Python
    col = getattr(model, spec)
    return query.order_by(col.desc() if order == "desc" else col.asc())

