EXCECOES_CAMPO_INPUT = {
    "vendas": {"cliente": "cliente_id", "veiculo": "veiculo_id",
               "veiculo_troca": "veiculo_troca_id", "vendedor": "vendedor_id"},
}

def campos_form_map(pagina: str, ignorar: set[str] = frozenset()) -> dict[str, str]:
    excecoes = EXCECOES_CAMPO_INPUT.get(pagina, {})
    return {
        campo: excecoes.get(campo, campo)
        for campo, _label in perfil.CAMPOS_PROTEGIDOS[pagina]
        if campo not in ignorar
    }

